def load_plugin_modules(self, modnames: list[str], force: bool = False) -> None:
    """Check a list of pylint plugins modules, load and register them.

    If a module cannot be loaded, store the error message for later use in
    ``load_plugin_configuration`` below. Already loaded plugins are skipped
    unless force is set, as needed to restore process-local state in workers.
    """
    for modname in modnames:
        if modname in self._dynamic_plugins and not force:
            continue
        try:
            module = astroid.modutils.load_module_from_name(modname)
            module.register(self)
